INSERT INTO nom_padecimiento (idpadecimiento, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (15, 'Acné', 'El acné es una inflamación de las unidades pilosebáceas de ciertas áreas del cuerpo (cara y tronco) que ocurre con mayor frecuencia en la adolescencia y se manifiesta como comedones, papulopústulas, o nódulos y quistes.', '2017-01-01', NULL, 1, NULL);
INSERT INTO nom_padecimiento (idpadecimiento, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (16, 'Aftas bucales', 'Un afta bucal es una pequeña úlcera o llaga abierta que aparece en el tejido mucoso que recubre el interior de la boca. Afectan normalmente a individuos de entre 10 y 40 años, y las mujeres son por lo general más propensas a padecerlas que los hombres.', '2017-01-01', NULL, 1, NULL);
INSERT INTO nom_padecimiento (idpadecimiento, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (17, 'Albinismo', 'El albinismo es un defecto hereditario que altera la producción y el metabolismo de la melanina, lo que se traduce en una ausencia total o parcial de este pigmento producido por unas células llamadas melanocitos.', '2017-01-01', NULL, 1, NULL);
INSERT INTO nom_padecimiento (idpadecimiento, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (18, 'Alcoholismo', 'El alcoholismo (o dependencia alcohólica) es uno de los principales motivos de consulta de salud mental, y se caracteriza por un consumo excesivo de alcohol durante un tiempo prolongado, que supone dependencia del mismo.', '2017-01-01', NULL, 1, NULL);
INSERT INTO nom_padecimiento (idpadecimiento, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (19, 'Alergia', 'La alergia se define como el estado de hipersensibilidad adquirida por la exposición a un alergeno particular, en el cual la nueva exposición ante dicha sustancia va a desencadenar una nueva reacción, si cabe, más intensa.', '2017-01-01', NULL, 1, NULL);
