INSERT INTO nom_tipocuentabancaria (idtipocuentabancaria, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (1, 'Depósito a la vista', 'Cuenta con iguales características que la corriente, excepto que no admite extracciones mediante cheques y devenga un interés.', '2019-01-01', NULL, 1, NULL);
INSERT INTO nom_tipocuentabancaria (idtipocuentabancaria, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (2, 'Depósito a plazo fijo', 'Cuenta en la que se sitúan fondos temporalmente libres con el compromiso del titular de no mover los mismos en un plazo determinado. Esta cuenta devenga intereses siempre que se cumpla con el plazo acordado.', '2019-01-01', NULL, 1, NULL);
INSERT INTO nom_tipocuentabancaria (idtipocuentabancaria, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (3, 'Administración de Fondos', 'Cuenta que recibe fondos de otras cuentas del titular, abiertas o no en el mismo banco. Desde esta cuenta sólo se podrán realizar pagos a través de cheques de gerencia, transferencias bancarias y tarjetas magnéticas (tarjetas internacionales y tarjetas para compras mayoristas), o mover fondos hacia otras cuentas del propio titular.', '2019-01-01', NULL, 1, NULL);
INSERT INTO nom_tipocuentabancaria (idtipocuentabancaria, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (4, 'Ingreso', 'Cuenta que recibe solamente ingresos  para ser transferidos a una cuenta corriente del propio titular abierta o no en el mismo banco.', '2019-01-01', NULL, 1, NULL);
INSERT INTO nom_tipocuentabancaria (idtipocuentabancaria, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (5, 'Cuenta para proyectos de colaboración financiados por donaciones', 'Cuenta corriente que se crea con el fin de administrar una donación destinada a la consecución de un objetivo a través de un proyecto.', '2019-01-01', NULL, 1, NULL);
INSERT INTO nom_tipoestanciaexterior (idtipoestanciaexterior, denominacion, descripcion, fdesde, fhasta, gestion, abreviatura) VALUES (1, 'Temporal', NULL, '2019-01-01', NULL, 1, NULL);
