INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1122, 'Banco', 1119, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":"true","forceSelection":"true","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"","anchor":"100%","displayField":"denominacion","emptyText":"Seleccione...","fieldLabel":"Banco","hiddenName":"idbanco","loadingText":"","mode":"local","name":"idbanco","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"idbanco"}', 'tag_blue', 3, '{"handler":"","store":"{\n  url: \"getBancos\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",          \n            root: \"data\"\n      },\n        mapping: [\n          \t{name: ''idbanco''},\n          \t{name: ''denominacion'', mapping:''nombre''},\n        \t{name: ''codigo''},\n        \t{name: ''abreviatura''}        \n        ],\n          autoLoad:true,\n          \n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":""}}', '{"module":"persona","component":"templates"}', NULL);
