INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1061, 'Estado de salud', 1054, 'basetecnologica', NULL, 2, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"true","disabled":"false","frame":"true","hidden":"false","split":"true","trackResetOnLoad":"true","elementsByRow":1,"height":"","anchocolumna":"","buttonAlign":"right","cmargins":"","collapseMode":"mini","html":"","labelAlign":"top","layout":"","margins":"5 5 5 0","region":"east","title":"Estado de salud actual","width":"30%"}', 'agrupador', 2, '{"helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getDatosSalud'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      this.arrAdd = [];\n      this.arrMod = [];\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        if(this.getForm().findField(''idaptitudfisica''))\n        \tthis.getForm().findField(''idaptitudfisica'').setRawValue(dataResponse.data.denomaptitudfisica);\n        if(this.getForm().findField(''limitacion''))\n        \tthis.getForm().findField(''limitacion'').setRawValue(dataResponse.data.limitacion);        \n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function(){\n  if (this.getForm().isValid() && this.getForm().isDirty()) {\n    var values = this.getForm().getValues();\n    if(Ext.isEmpty(values.idestadosalud)){\n    \tthis.arrAdd = [values];\n    }else{\n    \tthis.arrMod = [values];\n    }\n  }\n  return {\n    arrAdd: this.arrAdd,\n    arrMod: this.arrMod\n  };\n}","listeners":{"expand":"","focus":"","render":"","resize":""}}', '{"module":"persona","component":"templates"}', NULL);
