INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1194, 'Observaciones', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","elementsByRow":1,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Observaciones","width":"auto"}', 'tag', 4, '{"columns":"[ \n  {header: \"Observaciones\",width:400 , dataIndex: \"observacion\"},\n  {header: \"Fecha registro\",width:100 , dataIndex: \"fregistro\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function () {\n  var values = this.fpFormulario.getForm().getValues();\n  var fecha = new Date();\n  var month = fecha.getMonth()+1;\n  var day = fecha.getDate();\n  var year = fecha.getFullYear();\n \n  values.fregistro=day + ''/'' + month + ''/'' + year;\n  \n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idobservacion)) {\n    values.idobservacion = Ext.id();\n    values.add = true;\n    Ext.each(store.getRange(), function (rec) {\n      if (rec.get(''observacion'') == values.observacion) {\n        index = ''observacion'';\n        return false;\n      }\n    });\n    switch (index) {\n      case ''observacion'':\n        mostrarMensaje(6, ''La observación que quiere adicionar ya existe.'');\n        break;\n      default:\n        try {\n          store.add(new Ext.data.Record(values));\n          this.cleanForm();\n        } catch (error) {\n          mostrarMensaje(6, ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'');\n        }\n        break;\n    }\n  }\n}","eliminarHandler":"function ()\n{\n  var records = this.gpGrid.getSelectionModel().getSelections();\n   var ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la observación seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las observaciones seleccionadas?'';\n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n                var records = this.gpGrid.getSelectionModel().getSelections();\n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idobservacion''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function () {\n  var values = this.fpFormulario.getForm().getValues();\n  var fecha = new Date();\n  var month = fecha.getMonth()+1;\n  var day = fecha.getDate();\n  var year = fecha.getFullYear();\n  values.fregistro=day + ''/'' + month + ''/'' + year;\n  \n  var store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idobservacion)) {\n    values.idobservacion = Ext.id();\n    values.add = true;\n    Ext.each(store.getRange(), function (rec) {\n      if (rec.get(''observacion'') == values.observacion) {\n        index = ''observacion'';\n        return false;\n      }\n    });\n    switch (index) {\n      case ''observacion'':\n        mostrarMensaje(6, ''La observación que quiere adicionar ya existe.'');\n        break;\n      default:\n        try {\n          store.add(new Ext.data.Record(values));\n          this.cancelarHandler();\n        } catch (error) {\n          mostrarMensaje(6, ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'');\n        }\n        break;\n    }\n  } else {\n    var record;\n    Ext.each(store.getRange(), function (rec, i) {\n      if (rec.get(''idobservacion'') == values.idobservacion) { //Si  es el que se va a modificar\n        record = rec; //Obtengo el record que se va a modificar\n      } else if (rec.get(''idobservacion'') == values.idobservacion) {\n        index = ''observacion'';\n      }\n    });\n    switch (index) {\n      case ''observacion'':\n        mostrarMensaje(6, ''La observación ya existe.'');\n        break;\n      default:\n        try {\n          for (var p in values) {\n            if (values[p] != record.get(p)) {\n              record.set(p, values[p]);\n            }\n          }\n          this.cancelarHandler();\n        } catch (error) {\n          mostrarMensaje(6, ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'');\n        }\n        break;\n    }\n  }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"","saveFn":"function(btnPress){\n  var self = this;\n  var store = this.gpGrid.getStore();\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec) {\n    if (rec.data.add) {\n      this.arrAdd.push(rec.data);\n    } else {\n      if (!Ext.isEmpty(rec.modified)) {\n        this.arrMod.push(rec.data);\n      }\n    }\n  }, this);\n  if(this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: ''gestObservacion'',\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification) {\n        var dataResponse = Ext.decode(response.responseText);\n        if(dataResponse.success) {\n          if(btnPress === ''APLICAR'') {\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          mostrarMensaje(1, ''Los cambios han sido aplicados satisfactoriamente'');\n        } else {\n          mostrarMensaje(6, dataResponse.mensaje);\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}\n\n","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getObservacion\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idobservacion\"},\n          {name: \"observacion\"},\n          {name: \"fregistro\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1048, 'Misiones', 1043, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":"true","forceSelection":"true","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"0.30","anchor":"100%","displayField":"denominacion","emptyText":"Seleccione...","fieldLabel":"Misión","hiddenName":"idmision","loadingText":"","mode":"local","name":"idmision","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"","valueField":"idmision"}', 'icondistra-tag_blue', 3, '{"handler":"","store":"{\n  url: \"getMisiones\",\n    type: \"Store\",\n       baseParams: {\n            value: 1\n        },\n      reader: {\n        type: \"JsonReader\",          \n            root: \"data\"\n      },\n        mapping: [\n          {name: ''idmision''},\n          {name: ''idtipomision''},\n          {name: ''denominacion''},\n          {name: ''fdesde''},\n          {name: ''fhasta''},\n          {name: ''descripcion''}        \n        ],\n          autoLoad:true,\n          \n}","tpl":"","listeners":{"expand":"function (cmp) {\n \n  if(Ext.getCmp(''1052''+this.idpadre).getValue()){\n    cmp.store.filter(''idtipomision'', Ext.getCmp(''1052''+this.idpadre).getValue(), true);\n  }\n   \n}","focus":"","render":"","select":"function(cb, rec){\n  //ComboBox de Tipo de Mision\n  if (Ext.getCmp(''1052''+this.idpadre))\n  \tExt.getCmp(''1052''+this.idpadre).setValue(rec.get(''idtipomision''));\n}"}}', '{"module":"persona","component":"templates"}', NULL);
