INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1395, 'Módulo de Aseo', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":3,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Aseo","width":"auto"}', 'icondistra-tag', 13, '{"columns":"[\n  {header: \"Aseo\", width: 200, sortable: true, dataIndex: \"denomaseo\"},  \n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n    values.denomaseo = Ext.getCmp(\"1397\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idaseop)) {\n        values.idaseop = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){\n  \n  var records = this.gpGrid.getSelectionModel().getSelections();\n  var ask = ''¿Está seguro que quiere eliminar el aseo seleccionado?'';\n  if (records.length > 1) {\n    var ask = ''¿Está seguro que quiere eliminar los aseos seleccionados?'';\n  } \n  mostrarMensaje(2, ask, function (btn)\n                 {\n                   if (btn == ''ok'') {\n                     var records = this.gpGrid.getSelectionModel().getSelections();\n                     Ext.each(records, function (rec)\n                              {\n                                if (!rec.data.add) {\n                                  this.arrDel.push(rec.get(''idaseop''));\n                                }\n                                this.gpGrid.getStore().remove(rec);\n                              }, this);\n\n                     this.gpGrid.getView().refresh();\n                   }\n                 }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\t\n    values.denomaseo = Ext.getCmp(\"1397\" + this.idpadre).getRawValue();\n    var store = this.gpGrid.getStore();\n    var index = -1;\n\n    if (Ext.isEmpty(values.idaseop)) {\n        values.idaseop = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n      \n      \n      \n      var record;\n      \n      \n      \n       Ext.each(store.getRange(), function (rec)\n               {\n                 if (rec.get(''idaseop'') == values.idaseop) {                   \n                   record = rec;\n                   return false;\n                 }\n               });\n      \n       \n        switch (index) {             \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                \n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  var record = this.gpGrid.getSelectionModel().getSelected();  \n  this.loadFormulario(record);\n  \n}","saveFn":"function (btnPress)\n{\n    var store = this.gpGrid.getStore();\n    var self = this;\n    var pass = false;\n    this.arrAdd = [];\n    this.arrMod = [];\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n    }, this);\n    \n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modAseop'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''deltAseop'';\n        } else {\n            url = ''addAseop'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg;\n                    switch (url) {\n                        case ''modAseop'':\n                            msg = ''El aseo se ha modificado satisfactoriamente.'';\n                            break;\n                        case ''deltAseop'':\n                            msg = ''El aseo se ha eliminado satisfactoriamente.'';\n                            break;\n                        case ''addAseop'':\n                            msg = ''El aseo se ha adicionado satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getAseop\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idaseop\"},\n          {name: \"idaseo\"},\n          {name: \"denomaseo\"},\n          {name: \"fdesde\"},\n          {name: \"idpersona\"},\n          {name: \"fhasta\"}       \n        ]\n          \n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (75, 'fdesde', 68, 'basetecnologica', NULL, 3, '{"xtype":"datefield","allowBlank":"true","disabled":"false","hidden":"false","readOnly":"false","selectOnFocus":"false","showToday":"true","anchocolumna":"0.3","anchor":"100%","emptyText":"","fieldLabel":"Desde","format":"d/m/Y","hiddenName":"","name":"fdesde","value":"","vtype":""}', 'icondistra-tag_blue', 7, '{"listeners":{"change":"function(dt, newDate){\n  Ext.getCmp(''76''+this.idpadre).setMinValue(newDate);\n}","focus":"","render":"function(dt){\n  dt.setMaxValue(new Date());\n}"}}', 'null', NULL);
