INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (21, 'Estructura de alojamiento', 19, 'basetecnologica', NULL, 3, '{"xtype":"tree_combobox","allowBlank":"false","disabled":"false","editable":"true","hidden":"false","readOnly":"true","resizable":"false","anchocolumna":"","anchor":"98%","emptyText":"Seleccione...","fieldLabel":"Estructura de alojamiento","name":"denomalojamiento"}', 'icondistra-tag_blue', 3, '{"clickNode":"function (node, e) {\n  if (node.isLeaf()) {\n    var root = Ext.getCmp(''21'' + this.idpadre).tree.root.id;\n    var n = node;\n    var ruta = '''';\n    while(n.id != root) {\n      if(ruta != '''')\n        ruta = ruta + '' -> '' + n.text;\n      else\n        ruta = n.text;\n      n = n.parentNode;\n    }\n    console.info(ruta);\n    Ext.getCmp(''21'' + this.idpadre).setValue(node.id);\n    Ext.getCmp(''21'' + this.idpadre).setRawValue(ruta);    \n    this.collapse();\n    this.fireEvent(''selectNode'', node);\n  }\n}","reset":"","setValue":"","treeConfig":"{loader: {\n            dataUrl: ''/pvd/persona/index.php/nomestructalojamiento/getEstructAlojamiento''\n        },\n        border: false,\n        autoScroll: true,\n        rootVisible: false,\n        root: {\n            text: ''Estructura de alojamiento'',\n            animate: false,\n            draggable: false,\n            expanded: false\n        }}","listeners":{"expand":""}}', '{"module":"persona","component":"treecombobox"}', NULL);
