INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1304, 'Reserva', 1118, 'basetecnologica', 'Reserva', 1, '{"xtype":"grid_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Reserva","width":"auto"}', 'icondistra-tag', 5, '{"columns":"[ \n  {header: \"Entidad\",width:350 , dataIndex: \"entidad\"},\n  {header: \"ÿrea\",width:300 , dataIndex: \"area\"},\n  {header: \"Cargo\",width:300 , dataIndex: \"cargo\"},\n  {header: \"Sustituto\",width:50 , dataIndex: \"reserva\", renderer: function (val, metadata) {\n    if (val == 2) {\n      return ''<span style=\"color: #33aa33;\">'' + ''&#10004;'' + ''</span>'';\n    } else {\n      return ''<span style=\"color: #aa0710;\">'' + ''&#08416;'' + ''</span>'';\n    }\n  }},\n  {header: \"Preparación\",width:50 , dataIndex: \"preparacion\", renderer: function (val, metadata) {\n    if(val == ''1''){\n      return \"SI\";\n    } else if(val == ''0''){\n      return \"NO\";\n    }\n  }},\n  {header: \"Listo\",width:50 , dataIndex: \"listo\", renderer: function (val, metadata) {\n    if(val == ''1''){\n      return \"SI\";\n    } else if(val == ''0''){\n      return \"NO\";\n    }\n  }},\n  {header: \"Desde\",width:100 , dataIndex: \"fdesde\"},\n  {header: \"Hasta\",width:100 , dataIndex: \"fhasta\"}\n]","gSecurity":"","helpHandler":"","isDirty":"function(){\n\treturn false;\n}","loadFn":"function (idpersona)\n{\n  this.loadGridStore({idpersona: idpersona});\n}","saveFn":"","bbar":"","ptbar":"","sm":"","store":"{\n  url: \"getReserva\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idreserva\"},\n          {name: \"entidad\"},\n          {name: \"area\"},\n          {name: \"cargo\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"fregistro\"},\n          {name: \"reserva\"},\n          {name: \"preparacion\"},\n          {name: \"observacion\"},\n          {name: \"listo\"}\n        ]\n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1342, 'Situacion en la defensa', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Situación en la defensa","width":"auto"}', 'icondistra-tag', 8, '{"columns":"[\n  {header: \"Asignación en la defensa\", width: 200, sortable: true, dataIndex: \"denomasigdefensa\"},  \n  {header: \"Cargo\", width: 200, sortable: true, dataIndex: \"denomcargo\"},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomasigdefensa = Ext.getCmp(\"1345\" + this.idpadre).getRawValue();\n    values.denomcargo = Ext.getCmp(\"1344\" + this.idpadre).getRawValue();\n  \n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsituaciondefensa)) {\n        values.idsituaciondefensa = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){\n  \n  var records = this.gpGrid.getSelectionModel().getSelections();\n  var ask = ''¿Está seguro que quiere eliminar la situación seleccionada?'';\n  if (records.length > 1) {\n    var ask = ''¿Está seguro que quiere eliminar las situaciones seleccionadas?'';\n  } \n  \n  mostrarMensaje(2, ask, function (btn)\n                 {\n                   if (btn == ''ok'') {\n                     var records = this.gpGrid.getSelectionModel().getSelections();\n                     Ext.each(records, function (rec)\n                              {\n                                if (!rec.data.add) {\n                                  this.arrDel.push(rec.get(''idsituaciondefensa''));\n                                }\n                                this.gpGrid.getStore().remove(rec);\n                              }, this);\n\n                     this.gpGrid.getView().refresh();\n                   }\n                 }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.denomasigdefensa = Ext.getCmp(\"1345\" + this.idpadre).getRawValue();\n    values.denomcargo = Ext.getCmp(\"1344\" + this.idpadre).getRawValue();\n\t\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsituaciondefensa)) {\n        values.idsituaciondefensa = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n      \n      \n      \n      var record;\n      \n      \n      \n       Ext.each(store.getRange(), function (rec)\n               {\n                 if (rec.get(''idsituaciondefensa'') == values.idsituaciondefensa) {                   \n                   record = rec;\n                   return false;\n                 }\n               });\n      \n       \n        switch (index) {             \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                  console.info(values);\n                  console.info(error);\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  var record = this.gpGrid.getSelectionModel().getSelected();\n  //console.log(record);\n  \n  this.loadFormulario(record);\n  \n}","saveFn":"function (btnPress)\n{\n    var store = this.gpGrid.getStore();\n    var self = this;\n    var pass = false;\n    this.arrAdd = [];\n    this.arrMod = [];\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n    }, this);\n    \n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modSituacionDefensa'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delSituacionDefensa'';\n        } else {\n            url = ''addSituacionDefensa'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg;\n                    switch (url) {\n                        case ''modSituacionDefensa'':\n                            msg = ''La situación en la defensa se ha modificado satisfactoriamente.'';\n                            break;\n                        case ''delSituacionDefensa'':\n                            msg = ''La situación en la defensa se ha eliminado satisfactoriamente.'';\n                            break;\n                        case ''addSituacionDefensa'':\n                            msg = ''La situación en la defensa se ha adicionado satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getSituacionDefensa\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idsituaciondefensa\"},\n          {name: \"idasignaciondefensa\"},\n          {name: \"idcargodefensa\"},\n          {name: \"denomcargo\"},\n          {name: \"denomasigdefensa\"},\n          {name: \"fdesde\"},       \n          {name: \"fhasta\"}         \n        ]\n          \n}\n","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1362, 'Situaciones excepcionales', 1118, 'basetecnologica', NULL, 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Situaciones excepcionales","width":"auto"}', 'icondistra-tag', 10, '{"columns":"[\n  {header: \"Estructura situación excepcional\", width: 200, sortable: true, dataIndex: \"situacexcep\"},  \n  {header: \"Cargo situación excepcional\", width: 200, sortable: true, dataIndex: \"cargoexcep\"},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.situacexcep = Ext.getCmp(\"1366\" + this.idpadre).getRawValue();\n    values.cargoexcep= Ext.getCmp(\"1367\" + this.idpadre).getRawValue();\n  \n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsitexcepcional)) {\n        values.idsitexcepcional = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cleanForm();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","eliminarHandler":"function(){\n  \n  var records = this.gpGrid.getSelectionModel().getSelections();\n  var ask = ''¿Está seguro que quiere eliminar la situación seleccionada?'';\n  if (records.length > 1) {\n    var ask = ''¿Está seguro que quiere eliminar las situaciones seleccionadas?'';\n  } \n  mostrarMensaje(2, ask, function (btn)\n                 {\n                   if (btn == ''ok'') {\n                     var records = this.gpGrid.getSelectionModel().getSelections();\n                     Ext.each(records, function (rec)\n                              {\n                                if (!rec.data.add) {\n                                  this.arrDel.push(rec.get(''idsitexcepcional''));\n                                }\n                                this.gpGrid.getStore().remove(rec);\n                              }, this);\n\n                     this.gpGrid.getView().refresh();\n                   }\n                 }.createDelegate(this));\n}","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n\n    values.situacexcep = Ext.getCmp(\"1366\" + this.idpadre).getRawValue();\n    values.cargoexcep = Ext.getCmp(\"1367\" + this.idpadre).getRawValue();\n\t\n    var store = this.gpGrid.getStore();\n\n    var index = -1;\n\n    if (Ext.isEmpty(values.idsitexcepcional)) {\n        values.idsitexcepcional = Ext.id();\n        values.add = true;\n       \n        switch (index) {\n           \n            default :\n                try {\n                    store.add(new Ext.data.Record(values));\n                    this.cancelarHandler();\n                } catch (error) {\n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    } else {\n      \n      \n      \n      var record;\n      \n      \n      \n       Ext.each(store.getRange(), function (rec)\n               {\n                 if (rec.get(''idsitexcepcional'') == values.idsitexcepcional) {                   \n                   record = rec;\n                   return false;\n                 }\n               });\n      \n       \n        switch (index) {             \n            default :\n                try {\n                    for (var p in values) {\n                        if (values[p] != record.get(p)) {\n                            record.set(p, values[p]);\n                        }\n                    }\n                    this.cancelarHandler();\n                } catch (error) {\n                \n                    Ext.Notification.show({\n                        title: ''Error'',\n                        msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador.'',\n                        icon: ''error''\n                    });\n                }\n                break;\n        }\n    }\n}","helpHandler":"","isDirty":"","loadFn":"function (idpersona)\n{\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){\n  var record = this.gpGrid.getSelectionModel().getSelected();  \n  this.loadFormulario(record);\n  \n}","saveFn":"function (btnPress)\n{\n    var store = this.gpGrid.getStore();\n    var self = this;\n    var pass = false;\n    this.arrAdd = [];\n    this.arrMod = [];\n    Ext.each(store.getRange(), function (rec)\n    {\n        if (rec.data.add) {//Si es un record que se adiciono nuevo\n            this.arrAdd.push(rec.data);\n        } else {\n            if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n                this.arrMod.push(rec.data);\n            }\n        }\n    }, this);\n    \n    if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n        url = ''modSituacExcep'';\n    } else\n        if (this.arrDel.length > 0) {\n            url = ''delSituacExcep'';\n        } else {\n            url = ''addSituacExcep'';\n        }\n    if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n        Ext.sendAjax.request({\n            url: url,\n            params: {\n                arrAdd: Ext.encode(self.arrAdd),\n                arrMod: Ext.encode(self.arrMod),\n                arrDel: Ext.encode(self.arrDel)\n            },\n            success: function (response, opt, notification)\n            {\n                var dataResponse = Ext.decode(response.responseText);\n                if (dataResponse.success) {\n                    if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n                        this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n                    }\n                    this.arrAdd = [];\n                    this.arrMod = [];\n                    this.arrDel = [];\n                    var msg;\n                    switch (url) {\n                        case ''modSituacExcep'':\n                            msg = ''La situación excepcional se ha modificado satisfactoriamente.'';\n                            break;\n                        case ''delSituacExcep'':\n                            msg = ''La situación excepcional se ha eliminado satisfactoriamente.'';\n                            break;\n                        case ''addSituacExcep'':\n                            msg = ''La situación excepcional se ha adicionado satisfactoriamente.'';\n                            break\n                    }\n                    notification({\n                        title: ''Informaci&oacute;n'',\n                        msg: msg,\n                        icon: ''ok''\n                    });\n                } else {\n                    switch (dataResponse.codigo) {\n                        default :\n                            notification({\n                                title: ''Error'',\n                                msg: ''Ha ocurrido un error durante la transaccion.'',\n                                icon: ''error''\n                            });\n                            break;\n                    }\n                }\n            }.createDelegate(this)\n        }, this);\n    }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"RowSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getSituacExcep\",\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idsitexcepcional\"},\n          {name: \"idsituacexcep\"},\n          {name: \"idcargoexcep\"},\n          {name: \"situacexcep\"},\n          {name: \"cargoexcep\"},\n          {name: \"fdesde\"},       \n          {name: \"fhasta\"}         \n        ]\n          \n}","view":"","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
