INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (59, 'Foto de la persona', 58, 'basetecnologica', NULL, 2, '{"xtype":"gest_img","animCollapse":"false","autoHeight":"true","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":"2","height":120,"anchocolumna":"0.15","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"5 0 5 5","region":"west","title":"","width":"auto"}', 'icondistra-agrupador', 1, '{"gSecurity":"","helpHandler":"","isDirty":"","loadFn":"","saveFn":"","listeners":{"expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"gestionarimagenes"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1406, 'Disposición', 1147, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"true","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"0.2","anchor":"100%","displayField":"denominacion","emptyText":"Seleccione...","fieldLabel":"Disposición","hiddenName":"iddisposicion","loadingText":"","mode":"local","name":"iddisposicion","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"iddisposicion"}', 'icondistra-tag_blue', 6, '{"handler":"","store":"{\n  url: \"obtenerDisposiciones\",\n  type: \"Store\",\n  baseParams: {\n    value: 1\n  },\n  reader: {\n    type: \"JsonReader\",\n    root: \"data\"\n  },\n  mapping: [\n    {name: ''iddisposicion''},\n    {name: ''denominacion''},\n    {name: ''descripcion''},\n  ],\n  autoLoad:true\n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":"function(comp){\n  if (!Ext.getCmp(\"1404\" + this.idpadre).checked) {\n     comp.reset();\n  }\n}"}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (70, 'Sexo', 60, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":true,"forceSelection":"false","hidden":"false","readOnly":"true","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"","anchor":"100%","displayField":"denomsexo","emptyText":"Seleccione...","fieldLabel":"Sexo","hiddenName":"sexo","loadingText":"","mode":"local","name":"sexo","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"sexo"}', 'icondistra-tag_blue', 11, '{"handler":"","store":"{\n  type: \"SimpleStore\",\n    fields: [\n      {name: \"sexo\"},\n      {name: \"denomsexo\"},\n      {name: \"css\"}\n    ],\n      data: [\n        [\"1\", \"Masculino\", \"male\"],\n        [\"0\", \"Femenino\", \"female\"]\n      ]\n}","tpl":"''<tpl for=\".\"><div ext:qtip=\"{denomsexo}\" class=\"x-combo-list-item\"><img width=\"16\" height=\"16\" src=\"../../../../views/images/persona/{css}.png\">  {denomsexo}</div></tpl>''","listeners":{"expand":"","focus":"","render":"","select":"function (cb)\n{\n  Ext.getCmp(\"59\" + this.idpadre).setSexoImgDefault.call(Ext.getCmp(\"59\" + this.idpadre),cb.getValue());\n}"}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (58, 'Datos primarios', 57, 'basetecnologica', 'Datos generales de la persona', 1, '{"xtype":"panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"true","elementsByRow":"2","height":200,"anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Datos primarios","width":"auto"}', 'icondistra-tag', 0, '{"gSecurity":"function() {\n  var resp = true;\n  switch(Ext.getCmp(this.idpadre).accion) {\n    case ''ADD'':\n      if(parseInt(this.segAction[0]) === 1){ //Si puede adicionar\n        resp = false;\n      }\n      break;\n    case ''MOD'':\n      if(parseInt(this.segAction[1]) === 1){//Si puede modificar\n        resp = false;\n      }\n      break;\n  }\n  if(resp)\n    Ext.getCmp(\"60\" + this.idpadre).getForm().reset();\n  return resp;\n}","helpHandler":"","isDirty":"function() {\n  return Ext.getCmp(\"60\" + this.idpadre).getForm().isDirty();\n}","loadFn":"function (record) {\n  var values = Ext.getCmp(this.idpadre).persona;\n  values.sexo = (values.sexo === ''Femenino'' || values.sexo === ''0'') ? 0 : 1;\n  Ext.getCmp(\"60\" + this.idpadre).getForm().loadRecord(new Ext.data.Record(values));\n  Ext.getCmp(\"3\" + this.idpadre).setValue(values.idtipodocidentidad);\n  Ext.getCmp(\"3\" + this.idpadre).setRawValue(values.denomTipoDocIdentidad);\n  Ext.getCmp(\"4\" + this.idpadre).minLength=values.mincaracter;\n  Ext.getCmp(\"4\" + this.idpadre).maxLength=values.maxcaracter;\n  Ext.getCmp(\"4\" + this.idpadre).vtype=values.type;\n  Ext.getCmp(\"4\" + this.idpadre).maxLengthText=''El tamaño máximo requerido es ''+values.maxcaracter+'' caracteres.'';\n  Ext.getCmp(\"4\" + this.idpadre).minLengthText=''El tamaño mínimo requerido es ''+values.mincaracter+'' caracteres.'';\n  Ext.getCmp(\"4\" + this.idpadre).render();\n  var pFoto = Ext.getCmp(\"59\" + this.idpadre);\n  if (!Ext.isEmpty(values.foto)) {\n    pFoto.setImgPrincipal.call(pFoto, ''data:image/jpg;base64,'' + values.foto);\n  } else {\n    pFoto.setSexoImgDefault.call(pFoto, values.sexo);\n  }\n  pFoto.setPersona.call(pFoto, values.idpersona);\n}","saveFn":"function(btnPress){\n  var persona={};\n  if(Ext.getCmp(\"58\" + this.idpadre).gSecurity())return; //Si devuelve TRUE es porque tiene permisos para realizar la gestion correspondiente\n  \n  this.concept = \"principal\";\n  var accion = Ext.getCmp(this.idpadre).accion;\n  var pFoto = Ext.getCmp(\"59\" + this.idpadre)    \n   if (Ext.getCmp(\"60\" + this.idpadre).getForm().isValid() || pFoto.isDirty.call(pFoto)) {  \n    Ext.sendAjax.request({\n      url: accion == \"ADD\" ? ''addPerson'' : ''modPerson'',\n      params: {\n        persona: Ext.encode(Ext.getCmp(\"60\" + this.idpadre).getForm().getValues()),\n        fotos: Ext.encode(Ext.getCmp(\"59\" + this.idpadre).saveFn.call(Ext.getCmp(\"59\" + this.idpadre))),\n        fotoPrincipal:Ext.getCmp(\"59\" + this.idpadre).fotoPrincipal,\n        datos:Ext.encode(this.datos)\n        \n      },\n      success: function (response, opt, notification)\n      {        \n        var dataResponse = Ext.decode(response.responseText);\n       \n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') {\n            Ext.getCmp(this.idpadre).fireEvent(\"changeStatus\", dataResponse.datos);\n            \n          }\n         this.loadFn(dataResponse.datos);\n          var msg = (accion == ''ADD'')\n          ? ''La datos de la persona han sido adicionados satisfactoriamente.''\n          : ''La datos de la persona han sido modificados satisfactoriamente.'';\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            case 5:\n              notification({\n                title: ''Error'',\n                msg: ''Ya existe una persona con este número.'',\n                icon: ''error''\n              });\n              break;  \n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","listeners":{"expand":"function (cmp) {\n  if (cmp.rendered) {\n    cmp.doLayout();\n  }\n}","focus":"","render":"function(p){\n p.datos=new Array();\n   var accionTab=Ext.getCmp(p.idpadre).accion;\n if(!p.buscadorSuin){\n    p.buscadorSuin = new Ext.Persona.BuscadorSUIN();\n   if(accionTab==''ADD'' && p.fdatos==1){   \n     /*Ext.getCmp(\"61\" + this.idpadre).setDisabled(false);    \n     Ext.getCmp(\"62\" + this.idpadre).setDisabled(true);    \n     Ext.getCmp(\"63\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"64\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"3\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"4\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"70\" + this.idpadre).setDisabled(true);*/ \n     p.buscadorSuin.show();\n    \n   }else if(accionTab==''MOD'' && p.fdatos==1){\n     /*Ext.getCmp(\"61\" + this.idpadre).setDisabled(false);    \n     Ext.getCmp(\"62\" + this.idpadre).setDisabled(true);    \n     Ext.getCmp(\"63\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"64\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"3\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"4\" + this.idpadre).setDisabled(true);\n     Ext.getCmp(\"70\" + this.idpadre).setDisabled(true);*/\n   }else{\n     /*Ext.getCmp(\"61\" + this.idpadre).setDisabled(false);    \n     Ext.getCmp(\"62\" + this.idpadre).setDisabled(false);    \n     Ext.getCmp(\"63\" + this.idpadre).setDisabled(false);\n     Ext.getCmp(\"64\" + this.idpadre).setDisabled(false);\n     Ext.getCmp(\"3\" + this.idpadre).setDisabled(false);\n     Ext.getCmp(\"70\" + this.idpadre).setDisabled(false); \n     Ext.getCmp(\"4\" + this.idpadre).setDisabled(false);*/\n    \n    }\n     \n \t p.buscadorSuin.on(''rowselect'', function(rec){ \n       var pFoto = Ext.getCmp(\"59\" + this.idpadre);\n        if (!Ext.isEmpty(rec.data.foto)) {\n          pFoto.setImgPrincipal.call(pFoto, ''data:image/jpg;base64,'' + rec.data.foto);\n        }else{\n          pFoto.setSexoImgDefault.call(pFoto, rec.data.sexo);\n        }\n        //pFoto.setPersona.call(pFoto, rec.data.idpersona);\n        \n       Ext.getCmp(''60''+this.idpadre).purgeListeners();\n       Ext.getCmp(\"60\" + this.idpadre).getForm().loadRecord(rec); \n       Ext.getCmp(\"60\" + this.idpadre).getForm().updateRecord(rec);\n       Ext.each(rec,function(v){\n         p.datos.push(v.data);\n       })\n       Ext.getCmp(''btnAplicarPers'').enable();\n       Ext.getCmp(''btnAceptSavePers'').enable();\n       \n    },this)\n   \n  }\n  Ext.getCmp(\"61\" + this.idpadre).focus(true,200);\n   //Ext.getCmp(''btnAplicarPers'').disable();\n   //Ext.getCmp(''btnAceptSavePers'').disable();\n    \n}","resize":"function(cmp){\n  if (cmp.rendered && Ext.getCmp(\"60\" + this.idpadre).rendered && Ext.getCmp(\"59\" + this.idpadre).rendered) {\n    cmp.collapse();\n    cmp.expand(true);\n  }\n}","show":""}}', 'null', '{"class":"DatPersonaModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1147, 'Datos Sociales', 57, 'basetecnologica', NULL, 1, '{"xtype":"form_panel","animCollapse":"false","autoHeight":"true","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"true","hidden":"false","split":"false","trackResetOnLoad":true,"elementsByRow":5,"height":"","anchocolumna":"","anchor":"","buttonAlign":"right","cmargins":"","collapseMode":"","html":"","labelAlign":"top","layout":"","margins":"","region":"","title":"Datos Sociales","width":"auto"}', 'icondistra-tag', 11, '{"gSecurity":"function() {\n  var respuesta = true;\n  if (Ext.isEmpty(this.getForm().getValues().idcaracteristicasocial)) {\n    if (parseInt(this.segAction[0]) === 1) {\n      respuesta = false;\n    }\n  } else {\n    if (parseInt(this.segAction[1]) === 1) {\n      respuesta = false;\n    }\n  }\n  if (respuesta) {\n    Ext.getCmp(\"1147\" + this.idpadre).getForm().reset();\n  }\n  return respuesta;\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  Ext.Ajax.request({\n    url: ''getDatosSociales'',\n    params: {idpersona: idpersona},\n    success: function (response, opt)\n    {\n      var dataResponse = Ext.decode(response.responseText);\n      if (dataResponse.data) {\n        this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n        this.getForm().findField(''idestadocivil'').setRawValue(dataResponse.data.estadocivil);\n        this.getForm().findField(''idestratificacionsocial'').setRawValue(dataResponse.data.estratificaionsocial);\n        this.getForm().findField(''iddisposicion'').setRawValue(dataResponse.data.disposicion);\n        this.getForm().findField(''jubilado'').setValue(dataResponse.data.jubilado);\n      }\n    }.createDelegate(this)\n  });\n}","saveFn":"function(btnPress) {\n  if (Ext.getCmp(\"1147\" + this.idpadre).gSecurity()) {\n    return;\n  };\n  if (this.getForm().isValid() && this.getForm().isDirty()) {\n    var url = (Ext.isEmpty(this.getForm().getValues().idcaracteristicasocial)) ? ''addDatosSociales'' : ''modDatosSociales'';\n    var values = this.getForm().getValues();\n    values.jubilado = (Ext.getCmp(\"1404\" + this.idpadre).checked) ? 1 : 0;\n    Ext.sendAjax.request({\n      url: url,\n      params: values,\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') {\n            if (dataResponse.data) {\n              this.getForm().loadRecord(new Ext.data.Record(dataResponse.data));\n              this.getForm().findField(''idestadocivil'').setRawValue(dataResponse.data.estadocivil);\n              this.getForm().findField(''idestratificacionsocial'').setRawValue(dataResponse.data.estratificaionsocial);\n              this.getForm().findField(''iddisposicion'').setRawValue(dataResponse.data.disposicion);\n              this.getForm().findField(''jubilado'').setValue(dataResponse.data.jubilado);\n            }\n          }\n          var msg = '''';\n          switch (url) {\n            case ''addDatosSociales'':\n              msg = ''Los datos sociales han  sido adicionados satisfactoriamente.'';\n              break;\n            case ''modDatosSociales'':\n              msg = ''Los datos sociales se ha modificado satisfactoriamente.'';\n              break;\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n\n      }.createDelegate(this)\n    }, this);\n  }\n}","listeners":{"clientvalidation":"","expand":"","focus":"","render":"","resize":"","show":""}}', '{"module":"persona","component":"templates"}', '{"class":"DatCaracteristicasocialModel","function":"","id":"", "project":""}');
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1201, 'fhasta', 1195, 'basetecnologica', NULL, 3, '{"xtype":"datefield","allowBlank":"true","disabled":"false","hidden":"false","readOnly":"false","selectOnFocus":"false","showToday":"true","anchocolumna":"0.15","anchor":"100%","emptyText":"","fieldLabel":"Hasta","format":"d/m/Y","hiddenName":"fhasta","name":"fhasta","value":"","vtype":""}', 'icondistra-agrupador', 26, '{"listeners":{"change":"","focus":"","render":""}}', 'null', NULL);
