INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1407, 'categoriaocup', 1195, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"true","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"0.2","anchor":"100%","displayField":"categocup","emptyText":"","fieldLabel":"Categoría ocupacional","hiddenName":"categocup","loadingText":"","mode":"local","name":"categocup","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"all","valueField":"categocup"}', 'icondistra-tag_blue', 24, '{"handler":"","store":"{\n  url: \"obtenerCategOcupacional\",\n  type: \"Store\",\n  reader: {\n    type: \"JsonReader\",\n    root: \"\"\n  },\n  mapping: [\n    {name: ''categocup''}\n  ],\n  autoLoad:true\n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":""}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1199, 'motivobaja', 1195, 'basetecnologica', NULL, 3, '{"xtype":"tree_combobox","allowBlank":"true","disabled":"false","editable":"true","hidden":"false","readOnly":"false","resizable":"false","anchocolumna":"0.25","anchor":"100%","emptyText":"","fieldLabel":"Motivo de baja o movimiento","name":"denominacion"}', 'icondistra-agrupador', 29, '{"clickNode":"function (node, e) {\n        if (node.isLeaf()) {\n            var text = node.text;\n            this.setValue(text);\n            this.fireEvent(''selectNode'', node);\n            this.collapse();\n            Ext.getCmp(''1199'' + this.idpadre).setValue(node.attributes.id);\n        }\n    }","reset":"","setValue":"","treeConfig":"\n{loader: {\n            dataUrl: ''/pvd/persona/projects/basetecnologica/index.php/basetecnologica/getMotivosMovimiento''\n        },\n        border: false,\n        autoScroll: true,\n        rootVisible: false,\n        root: {\n            text: ''Motivos de movimiento'',\n            animate: false,\n            draggable: false,\n            expanded: false\n        }}","listeners":{"expand":""}}', '{"module":"persona","component":"treecombobox"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1197, 'ÿrea/Entidad/Organismo', 1195, 'basetecnologica', NULL, 3, '{"xtype":"combo_box","allowBlank":"false","disabled":"false","editable":"true","forceSelection":"false","hidden":"false","readOnly":"false","resizable":"false","selectOnFocus":"false","typeAhead":"false","anchocolumna":"0.25","anchor":"100%","displayField":"orgentidad","emptyText":"","fieldLabel":"Entidad","hiddenName":"","loadingText":"","mode":"local","name":"orgentidad","toolTipTrigger1":"","toolTipTrigger2":"","triggerAction":"","valueField":""}', 'icondistra-agrupador', 2, '{"handler":"","store":"{\n  url: \"getEntidad\",\n    autoLoad:true,\n   // baseParams:{idpersona:Ext.getCmp(''1195'' + this.idpadre).idpersona},\n    type: \"Store\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"orgentidad\"}\n        ]\n}","tpl":"","listeners":{"expand":"","focus":"","render":"","select":"function(combo,record,num){\n  \n // Ext.Ajax.request({\n\t//\turl:''getDenomEntidad'' ,\n\t//\tparams: {\n\t//\t\torgentidad: record.data.orgentidad\n  //  },\n//callback: function () {\n\n  //  },\n//success: function (r) {\n\t//var responseData = Ext.decode(r.responseText);\n\t\n  //  }\n///});\n  \n // console.info(record);\n // if (cmp.rendered && Ext.getCmp(\"60\" + this.idpadre).rendered && Ext.getCmp(\"59\" + this.idpadre).rendered) {\n   // cmp.collapse();\n    //cmp.expand(true);\n  //}\n}"}}', '{"module":"persona","component":"templates"}', NULL);
INSERT INTO dat_proyectoconcepto (idproyectoconcepto, denominacion, idpadre, idproyecto, descripcion, tipo, propiedades, iconcls, orden, codigo, cmpempleado, getdata) VALUES (1195, 'Trayectoria laboral', 67, 'basetecnologica', 'Trayectoria laboral de las personas', 1, '{"xtype":"gest_panel","animCollapse":"false","autoHeight":"false","border":"true","collapsed":"false","collapsible":"false","disabled":"false","frame":"false","hidden":"false","split":"false","elementsByRow":4,"height":"","anchocolumna":"","anchor":"","cmargins":"","collapseMode":"","html":"","layout":"","margins":"","region":"","title":"Trayectoria laboral","width":"auto"}', 'icondistra-tag', 4, '{"columns":"[\n  {header: \"Entidad\", width: 180,hidden: true, sortable: true, dataIndex: \"orgentidad\"},\n  {header: \"Fecha Alta\", width: 180,hidden: true, sortable: true, dataIndex: \"falta\"},\n  {header: \"Fecha Baja\", width: 180,hidden: true, sortable: true, dataIndex: \"fbaja\"},\n  {header: \"Cargo\", width: 180, sortable: true, dataIndex: \"cargo\"},\n  {header: \"Categoría ocupacional\", width: 150, sortable: true, dataIndex: \"categocup\"},\n  {header: \"No. alta/Resolución/Orden\", width: 180, sortable: true, dataIndex: \"noalta\"},   \n  {header: \"Motivo de baja o movimiento\", width: 200, sortable: true, dataIndex: \"denominacion\"},\n  {header: \"Desde\", width: 100, sortable: true, dataIndex: \"fdesde\"},\n  {header: \"Hasta\", width: 100, sortable: true, dataIndex: \"fhasta\"},\n  {header: \"Tiempo de servicio\", width: 150, sortable: true, renderer: function(value, metadata, record) {\n    var tyear = \"\";\n    var yearDenom = (record.data.tiempoa == 1) ? \" año \" : \" años \";\n    if (record.data.tiempoa > 0) {\n      tyear = record.data.tiempoa + yearDenom;\n    }\n    \n    var tmon = \"\";\n    var monDenom = (record.data.tiempom == 1) ? \" mes \" : \" meses \";\n    if (record.data.tiempom > 0) {\n      tmon = record.data.tiempom + monDenom;\n    }\n    \n    var tday = \"\";\n    var dayDenom = (record.data.tiempod == 1) ? \" día \" : \" días \";\n    if (record.data.tiempod > 0) {\n      tday = record.data.tiempod + dayDenom;\n    }\n    return tyear + tmon + tday;\n  }}\n]","addBotones":"","adicionarHandler":"","aplicarHandler":"function ()\n{\n  var values = this.fpFormulario.getForm().getValues();\n  \n   values.motivobaja=Ext.getCmp(''1199'' + this.idpadre).getValue();\n \n if(!Ext.isEmpty(values.orgentidad) || !Ext.isEmpty(values.cargo)){\n\tvar store = this.gpGrid.getStore();\n  var index = -1;\n  if (Ext.isEmpty(values.idtrayectorialaboral)){\n    values.idtrayectorialaboral = Ext.id();\n    values.add = true;\n   \n    try {\n      store.add(new Ext.data.Record(values));\n      this.cleanForm();\n    } catch (error) {\n      Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador.'',\n        icon: ''error''\n      });\n    }\n  }\n }else{\n  Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Debe especificar el campo ÿrea/Entidad/Organismo o el Cargo'',\n        icon: ''error''\n      });\n }\n \n  \n}","eliminarHandler":"function(){\n  \tvar records = this.gpGrid.getSelectionModel().getSelections();\n  \tvar ask = (records.length == 1) ? ''¿Está seguro que quiere eliminar la trayectoria laboral seleccionada?'' : \n    ''¿Está seguro que quiere eliminar las trayectorias laborales seleccionadas?'';\n  \n\tmostrarMensaje(2, ask, function (btn)\n        {\n            if (btn == ''ok'') {\n\n                var records = this.gpGrid.getSelectionModel().getSelections();\n                Ext.each(records, function (rec)\n                {\n                    if (!rec.data.add) {\n                        this.arrDel.push(rec.get(''idtrayectorialaboral''));\n                    }\n                    this.gpGrid.getStore().remove(rec);\n                }, this);\n                this.gpGrid.getView().refresh();\n            }\n        }.createDelegate(this));\n}\n","gSecurity":"","getLanguaje":"","guardarHandler":"function ()\n{\n    var values = this.fpFormulario.getForm().getValues();\n \n \n   values.motivobaja=Ext.getCmp(''1199'' + this.idpadre).getValue();\n \n  \n\tif(!Ext.isEmpty(values.orgentidad) || !Ext.isEmpty(values.cargo)){\n     \n    var store = this.gpGrid.getStore();\n\n    if (Ext.isEmpty(values.idtrayectorialaboral)) {\n       \n         values.idtrayectorialaboral = Ext.id();\n         values.add = true;\n        try {\n            store.add(new Ext.data.Record(values));\n            this.cancelarHandler();\n        } catch (error) {\n            Ext.Notification.show({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error mientras se guardaba, contacte el administrador'',\n                icon: ''error''\n            });\n        }\n    } else {\n      \n       \n        var record;\n        Ext.each(store.getRange(), function (rec)\n        {\n         \n          if(isNaN(values.motivobaja)){\n            values.motivobaja=rec.get(''motivobaja'');\n          }\n         \n          \n            if (rec.get(''idtrayectorialaboral'') == values.idtrayectorialaboral) {\n                record = rec;\n                return false;\n            }\n        });\n\n        try {\n            for (var p in values) {\n                if (values[p] != record.get(p)) {\n                    record.set(p, values[p]);\n                }\n            }\n            this.cancelarHandler();\n        } catch (error) {\n            Ext.Notification.show({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error mientras se modificaba, contacte el administrador'',\n                icon: ''error''\n            });\n        }\n\n    }\n }else{\n  Ext.Notification.show({\n        title: ''Error'',\n        msg: ''Debe especificar el campo ÿrea/Entidad/Organismo o el Cargo'',\n        icon: ''error''\n      });\n }\n}","helpHandler":"","isDirty":"","loadFn":"function(idpersona){\n  this.arrAdd = [];\n  this.arrMod = [];\n  this.arrDel = [];\n  this.loadGridStore({idpersona: idpersona});\n}","modificarHandler":"function(){  \n  var record = this.gpGrid.getSelectionModel().getSelected();  \n  this.loadFormulario(record);\n\n}","saveFn":"function (btnPress)\n{\n  var store = this.gpGrid.getStore();\n  var self = this;\n  var pass = false;\n  this.arrAdd = [];\n  this.arrMod = [];\n  Ext.each(store.getRange(), function (rec)\n  {\n   // console.info(rec.data);\n    if (rec.data.add) {//Si es un record que se adiciono nuevo\n      this.arrAdd.push(rec.data);\n    } else {\n      if (!Ext.isEmpty(rec.modified)) {//Si el record fue modificado\n        this.arrMod.push(rec.data);\n      }\n    }\n    pass = true;\n  }, this);\n  if (!pass && this.obligatorio) {\n    Ext.Notification.show({\n      title: ''Advertencia'',\n      msg: ''La persona debe tener un cargo registrado'',\n      icon: ''warning''\n    });\n    return false;\n  }\n  var url = '''';\n  if (this.arrMod.length > 0 || (this.arrDel.length > 0 && this.arrAdd.length > 0)) {\n    url = ''modTrayectoriaLaboral'';\n  } else\n    if (this.arrDel.length > 0) {\n      url = ''delTrayectoriaLaboral'';\n    } else {\n      url = ''addTrayectoriaLaboral'';\n    }\n  if (this.arrAdd.length > 0 || this.arrMod.length > 0 || this.arrDel.length > 0) {\n    Ext.sendAjax.request({\n      url: url,\n      params: {\n        arrAdd: Ext.encode(self.arrAdd),\n        arrMod: Ext.encode(self.arrMod),\n        arrDel: Ext.encode(self.arrDel)\n      },\n      success: function (response, opt, notification)\n      {\n        var dataResponse = Ext.decode(response.responseText);\n        //console.info(dataResponse.success);\n        if (dataResponse.success) {\n          if (btnPress === ''APLICAR'') { //Si el boton que ejecuto la funcion fue aplicar\n            this.loadFn(Ext.getCmp(this.idpadre).persona.idpersona);\n          }\n          this.arrAdd = [];\n          this.arrMod = [];\n          this.arrDel = [];\n          var msg;\n          switch (url) {\n            case ''modTrayectoriaLaboral'':\n              msg = ''Los datos se han modificado satisfactoriamente.'';\n              break;\n            case ''delTrayectoriaLaboral'':\n              msg = ''Los datos se han eliminado satisfactoriamente.'';\n              break;\n            case ''addTrayectoriaLaboral'':\n              msg = ''Los datos se han adicionado satisfactoriamente.'';\n              break\n          }\n          notification({\n            title: ''Informaci&oacute;n'',\n            msg: msg,\n            icon: ''ok''\n          });\n        } else {\n          switch (dataResponse.codigo) {\n            default :\n              notification({\n                title: ''Error'',\n                msg: ''Ha ocurrido un error durante la transaccion.'',\n                icon: ''error''\n              });\n              break;\n          }\n        }\n      }.createDelegate(this)\n    }, this);\n  }\n}","validateForm":"","bbar":"","ptbar":"","sm":"{\n  type: \"CheckboxSelectionModel\",\n  singleSelect: false\n}","store":"{\n  url: \"getTrayectoriaLaboralByPersona\",\n    type: \"GroupingStore\",\n      reader: {\n        type: \"JsonReader\",\n          totalProperty: \"quantity\",\n            root: \"data\"\n      },\n        mapping: [\n          {name: \"idtrayectorialaboral\"},\n          {name: \"idpersona\"},\n          {name: \"orgentidad\"},\n          {name: \"cargo\"},\n          {name: \"fdesde\"},\n          {name: \"fhasta\"},\n          {name: \"denominacion\"},\n          {name: \"observacion\"},\n          {name: \"falta\"},\n          {name: \"fbaja\"},\n          {name: \"noalta\"},\n          {name: \"motivobaja\"},\n          {name: \"tiempoa\"},\n          {name: \"tiempom\"},\n          {name: \"tiempod\"},\n          {name: \"categocup\"}\n        ],\n          sortInfo: {field: ''orgentidad'', direction: \"DESC\"},\n          groupField: ''orgentidad''\n}\n","view":"{\n type: ''GroupingView'',\n    startCollapsed: false,\n      groupTextTpl: ''{text}  Fecha Alta:{[values.rs[0].data.falta]} Fecha Baja:{[values.rs[0].data.fbaja]}''\n       \n}\n","viewConfig":"","listeners":{"beforeload":"","expand":"","focus":"","load":"","render":"","resize":"","selectionchange":"","show":""}}', '{"module":"persona","component":"templates"}', NULL);
