   WHERE (old.tipo = (0)::numeric) DO INSTEAD NOTHING;
CREATE RULE regla_update AS
    ON UPDATE TO nom_concepto
   WHERE (old.tipo = (0)::numeric) DO INSTEAD NOTHING;
